// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }

    // fuzz parameters: depositor private key k (uint256) and deposit amount
    function testFuzz_property(uint256 privKey, uint256 deposit) public {
        // Keep privKey in secp256k1 range and nonzero, and deposit in a reasonable bound
        uint256 SECP_ORDER = 0xFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFEBAAEDCE6AF48A03BBFD25E8CD0364141;
        vm.assume(privKey > 0 && privKey < SECP_ORDER);
        deposit = bound(deposit, 0, 1 ether);

        address depositor = vm.addr(uint256(privKey));

        // Only consider positive deposits because depositing zero is vacuous
        vm.assume(deposit > 0);

        // Fund depositor externally so they can send ETH
        vm.deal(depositor, deposit);

        // depositor calls addToBalance paying `deposit`
        vm.prank(depositor);
        c.addToBalance{value: deposit}();

        // Record contract balance before withdraw
        uint256 before = address(c).balance;

        // depositor calls withdrawBalance; capture whether it succeeded (no revert)
        bool ok;
        vm.prank(depositor);
        try c.withdrawBalance() {
            ok = true;
        } catch {
            ok = false;
        }

        // After a successful withdraw on the reference contract:
        //  - caller should receive their deposited amount (so contract balance decreased by deposit)
        // We assert the reference property universally for all admissible inputs: if call did not revert,
        // then address(c).balance == before - deposit
        if (ok) {
            assertTrue(address(c).balance + deposit == before);
        } else {
            // If withdraw reverted, the reference would also revert for same scenario; still accept that path
            assertTrue(address(c).balance == before);
        }
    }
}
